using EqlTracker.Core;

static class GroupingTests
{
    static readonly DateTime t = new(2026,10,19,12,0,0);
    static void Check(bool value,string message="Grouping assertion failed") { if(!value)throw new Exception(message); }
    static string Log(string text,int second) => $"[{t.AddSeconds(second):ddd MMM dd HH:mm:ss yyyy}] {text}";
    static GroupingEvidence Evidence(params (string,int)[] lines) { var e=new GroupingEvidence();foreach(var (text,second) in lines)e.Observe(Log(text,second),"gen:"+second);return e; }
    static CombatEvent Hit(string id,string actor,long amount,int second,string target="Mob") => new(){Id=id,Time=t.AddSeconds(second),Actor=actor,Owner=actor=="Rune"?"Player":actor=="Earthpet"?"Pet":"Group",Target=target,Ability="Slash",Kind="Melee",Damage=amount,Outcome="Hit"};
    static (CharacterProfile,Encounter,DpsViewState) Fixture()
    {
        var p=new CharacterProfile{Character="Rune",Meter=new(){Actor="Combined",Scope="Session"},PetIdentities=[new(){Name="Earthpet",From=t,Element="Earth"}],GroupMembers=[new(){Name="Ally",From=t,Until=t.AddSeconds(40)},new(){Name="Wolf",From=t,Until=t.AddSeconds(40),IsPet=true,Owner="Ally"},new(){Name="Silent",From=t,Until=t.AddMinutes(2)}]};
        var e=new Encounter{Id="fight",Start=t,End=t.AddMinutes(1),PlayerDamage=100,PetDamage=50,Events=[Hit("1","Rune",100,5),Hit("2","Earthpet",50,6),Hit("3","Ally",200,8),Hit("4","Wolf",25,9),Hit("5","Nearby",999,10),Hit("6","Ally",500,50),Hit("7","Mob",999,11,"Rune")]};
        return(p,e,DpsViews.Build([e],null,t,p.Meter));
    }
    public static void Register(Action<string,Action> test)
    {
        test("Grouping stays one period through member rotation and zoning",()=>{var e=Evidence(("You have joined the group.",0),("A has joined the group.",1),("A has left the group.",2),("B has joined the group.",3),("You have entered Freeport.",4),("You have left the group.",5));Check(e.Periods.Count==1&&e.Periods[0].Members.Count==2&&e.Periods[0].End==t.AddSeconds(5));});
        test("A fresh explicit join closes an unobserved earlier leave",()=>{var e=Evidence(("You have joined the group.",0),("A has joined the group.",1),("You have joined the group.",10));Check(e.Periods.Count==2&&e.Periods[0].UncertainEnd&&e.Periods[0].End==t.AddSeconds(1)&&e.Periods[1].Start==t.AddSeconds(10));});
        test("Grouping accepted invitation and joined marker share stable period",()=>{var e=Evidence(("You notify Ally that you agree to join the group.",0),("You have joined the group.",0));Check(e.Periods.Count==1&&!e.Periods[0].InferredStart&&e.Periods[0].Members.Single().Name=="Ally");});
        test("Five historical rotating players do not imply a raid",()=>{var e=Evidence(("You have joined the group.",0));for(int i=1;i<=6;i++){e.Observe(Log($"P{i} has joined the group.",i*2),"gen:"+(i*2));e.Observe(Log($"P{i} has left the group.",i*2+1),"gen:"+(i*2+1));}Check(e.Periods.Single().Kind==PartyKind.Group);});
        test("Concurrent verified fifth player infers raid and remains raid after leave",()=>{var e=Evidence(("You have joined the group.",0),("A has joined the group.",1),("B has joined the group.",2),("C has joined the group.",3),("D has joined the group.",4),("D has left the group.",5));Check(e.Periods.Single().Kind==PartyKind.Raid&&e.Periods.Single().RaidEvidence.Single().Inferred);});
        test("Raid-only system evidence detects underfilled raid",()=>{var e=Evidence(("You receive no experience for defeating this creature as you are in a raid.",1));Check(e.Periods.Single().Kind==PartyKind.Raid&&e.Periods.Single().InferredStart&&!e.Periods.Single().RaidEvidence.Single().Inferred);});
        test("Raid channel observes member without inventing interval",()=>{var e=Evidence(("Ally tells the raid, 'hello'",1));var m=e.Periods.Single().Members.Single();Check(m.PointOnly&&m.Until==m.From);});
        test("Raid words inside ordinary chat are not raid evidence",()=>{var e=Evidence(("You tell General:1, 'You receive no experience for defeating this creature as you are in a raid.'",1));Check(e.Periods.Count==0);});
        test("Login and log rotation close grouping with uncertain ends",()=>{var e=Evidence(("You have joined the group.",0),("You hit a mob.",2),("Welcome to EverQuest Legends!",5));Check(e.Periods.Single().End==t.AddSeconds(2)&&e.Periods.Single().UncertainEnd);e.Observe(Log("A has joined the group.",6),"newgen:1");Check(e.Periods.Count==2);});
        test("Grouping checkpoint state resumes without duplicates",()=>{var e=Evidence(("You have joined the group.",0),("A has joined the group.",1));e=System.Text.Json.JsonSerializer.Deserialize<GroupingEvidence>(System.Text.Json.JsonSerializer.Serialize(e))!;e.Observe(Log("A has joined the group.",1),"gen:1");Check(e.Periods.Count==1&&e.Periods[0].Members.Count==1);});
        test("Owner rows fold only verified pets and exclude incoming and unrelated actors",()=>{var(p,e,v)=Fixture();var g=GroupProjection.Build(v,null,p,[],"g");Check(g.Total==375&&g.Members.Single(m=>m.Name=="Self").Total==150&&g.Members.Single(m=>m.Name=="Ally").Total==225);Check(g.Members.Count==3&&g.Members.Sum(m=>m.Share??0)==100);});
        test("Member details retain owner and pet arithmetic",()=>{var(p,e,v)=Fixture();var row=GroupProjection.Build(v,null,p,[],"g").Members.Single(m=>m.Name=="Ally");Check(row.CharacterTotal==200&&row.PetTotal==25&&row.Abilities.Sum(a=>a.Damage)==225&&row.Details.Single().Value.Contains("225"));});
        test("Unknown pet ownership cannot boost a recommendation or group row",()=>{var(p,e,v)=Fixture();p.GroupMembers.Single(m=>m.IsPet).Owner="";var g=GroupProjection.Build(v,null,p,[],"g");Check(g.Members.Single(m=>m.Name=="Ally").Total==200&&g.Total==350);});
        test("Member without observed combat remains unknown",()=>{var(p,e,v)=Fixture();var m=GroupProjection.Build(v,null,p,[],"g").Members.Single(m=>m.Name=="Silent");Check(m.Total==null&&m.Rate==null&&m.Share==null);});
        test("Point-only raid roster observations do not capture nearby damage",()=>{var(p,e,v)=Fixture();p.GroupMembers=[];var period=new GroupPeriod{Start=t,LastObserved=t.AddMinutes(1),Members=[new(){Name="Ally",From=t,Until=t,PointOnly=true}]};Check(GroupProjection.Build(v,null,p,[period],"g").Members.Single(m=>m.Name=="Ally").Total==null);});
        test("Group filtering preserves original durations and personal calculations",()=>{var(p,e,v)=Fixture();long before=e.Damage;var times=(e.Start,e.End);p.Meter.Ability="Slash";var g=GroupProjection.Build(v,null,p,[],"g");Check(g.Seconds==60&&g.Members.Single(m=>m.Name=="Ally").Rate==225d/60&&before==e.Damage&&times==(e.Start,e.End)&&v.Damage==150);});
        test("Group healing includes verified other healers and owned pets",()=>{var(p,e,v)=Fixture();e.Heals=[new(){Id="h1",Time=t.AddSeconds(10),Healer="Ally",Recipient="Rune",HealerOwner="Group",Effective=80,Ability="Heal"},new(){Id="h2",Time=t.AddSeconds(11),Healer="Wolf",Recipient="Rune",HealerOwner="Group",Effective=20,Ability="Heal"}];var h=HealingMetrics.Build([e],[],new());var g=GroupProjection.Build(v,h,p,[],"g");Check(g.Members.Single(m=>m.Name=="Ally").Total==100&&g.Members.Single(m=>m.Name=="Ally").PetTotal==20);});
        test("Summary-only group data remains unavailable",()=>{var(p,e,v)=Fixture();e.Events=[];e.DetailAvailable=false;var g=GroupProjection.Build(v,null,p,[],"g");Check(g.Members.All(m=>m.Total==null)&&g.Coverage.Contains("Summary-only"));});
        test("Group projection cancellation is cooperative",()=>{var(p,e,v)=Fixture();using var c=new CancellationTokenSource();c.Cancel();try{GroupProjection.Build(v,null,p,[],"g",c.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){}});
        test("New selection fields persist independently and preserve personal actor",()=>{var p=new CharacterProfile();p.OverlayMeter=new(){Actor="Pet",DisplayMode=OverlayCombatMode.Group,GroupPeriodId="old"};var copy=p.OverlayMeter.Copy();copy.ClassCombinations.Add("WAR");Check(copy.DisplayMode==OverlayCombatMode.Group&&copy.GroupPeriodId=="old"&&p.OverlayMeter.ClassCombinations.Count==0&&p.Meter.Actor=="Pet");Check(p.OverlayMenus==OverlayMenuSize.Compact);});
        test("Session roster without encounters remains known while old sessions are excluded",()=>{var(p,e,v)=Fixture();p.GroupMembers.Add(new(){Name="Old member",From=t.AddDays(-2),Until=t.AddDays(-1)});var session=new PlaySession{Start=t,LastObserved=t.AddMinutes(2),Members=p.GroupMembers.Where(m=>m.Name=="Silent").ToList()};var empty=DpsViews.Build([],null,t,p.Meter,[session]);var g=GroupProjection.Build(empty,null,p,[],"empty");Check(g.Members.Any(m=>m.Name=="Silent"&&m.Total==null)&&!g.Members.Any(m=>m.Name=="Old member"));});
        test("Raid roster-only observations survive a session with no retained fights",()=>{var(p,e,v)=Fixture();p.GroupMembers=[];var session=new PlaySession{Start=t,LastObserved=t.AddMinutes(2)};var empty=DpsViews.Build([],null,t,p.Meter,[session]);var period=new GroupPeriod{Start=t,LastObserved=t.AddMinutes(1),Members=[new(){Name="Raid observer",From=t,Until=t,PointOnly=true}]};Check(GroupProjection.Build(empty,null,p,[period],"empty").Members.Any(m=>m.Name=="Raid observer"&&m.Total==null));});
        test("Context filters apply equally to folded group contributions",()=>{var(p,e,v)=Fixture();p.Meter.CriticalOnly=true;v=DpsViews.Build([e],null,t,p.Meter);Check(GroupProjection.Build(v,null,p,[],"g").Total==0);});
    }
}
